      shafii: 'كل جرم يحول بين الماء والبشرة أو الظفر يبطل الطهارة.',
      hanbali: 'يجب نزعه قبل الوضوء؛ لأن غسل اليدين مع الأظافر ركن مفروض.',
      dalil: 'حديث عمر رضي الله عنه أن رجلاً توضأ فترك موضع ظفر على قدمه فأبصره النبي ﷺ فقال: «ارجع فأحسن وضوءك».',
    ),
    FiqhItem(
      id: 'tahara_17',
      categoryId: 'tahara',
      question: 'ما حكم الوضوء مع وجود المكياج على الوجه؟',
      summary: 'إن كان المكياج عازلاً كالكريمات المقاومة للماء والطبقات السميكة لم يصح الوضوء، وإن كان مجرد لون كدهن خفيف لا يمنع نفوذ الماء صح الوضوء.',
      hanafi: 'الدهن الخفيف ومجرد اللون لا يمنع صحة الوضوء.',
      maliki: 'ما كان له جرم يمنع وصول الماء يوجب الإزالة، وما كان أثراً ولوناً فلا حرج.',
      shafii: 'يشترط ألا يكون على العضو حائل يمنع ملامسة الماء للبشرة.',
      hanbali: 'إذا كان المكياج يمنع وصول الماء وجبت إزالته، وإن كان يسيراً نفاذاً صح الوضوء.',
      dalil: 'الأمر بغسل الوجه كاملاً في آية الوضوء ﴿فَاغْسِلُوا وُجُوهَكُمْ﴾.',
    ),
    FiqhItem(
      id: 'tahara_18',
      categoryId: 'tahara',
      question: 'إذا لمس رجل أجنبي (غير مَحْرَم) يدي، هل ينتقض وضوئي؟',
      summary: 'الشافعية: ينتقض وضوء اللامس والملموس مطلقاً. المالكية والحنابلة: ينتقض إن كان بشهوة ولذة فقط. الحنفية: لا ينتقض الوضوء بلمس الأجنبي مطلقاً.',
      hanafi: 'لا ينتقض الوضوء بلمس المرأة ولو بشهوة إلا بالمباشرة الفاحشة.',
      maliki: 'ينتقض إن وجد لذة أو قصدها، ولا ينتقض باللمس العارض العفوي بغير شهوة.',
      shafii: 'ينتقض وضوء الرجل والمرأة بمجرد التقاء البشرتين بغير حائل مطلقاً.',
      hanbali: 'ينتقض بلمس المرأة لشهوة، ولا ينتقض بغير شهوة.',
      dalil: 'قوله تعالى: ﴿أَوْ لَامَسْتُمُ النِّسَاءَ﴾ وتفسير ابن عباس لها بالجماع وتفسير ابن مسعود باللمس باليد.',
    ),
    FiqhItem(
      id: 'tahara_19',
      categoryId: 'tahara',
      question: 'هل يجوز للمرأة المسح على الحجاب أو الخمار في الوضوء؟',
      summary: 'يجوز عند الحنابلة إذا كان مداراً تحت الحنك ويشق نزعه. والجمهور يشترطون مسح الرأس مباشرة أو إدخال اليد تحته.',
      hanafi: 'لا يجزئ المسح على الخمار إلا إن بلّ الماء شعر الرأس من تحته.',
      maliki: 'لا يصح المسح على الخمار ويجب مسح شعر الرأس مباشرة.',
      shafii: 'يجوز مسح بعض شعر الرأس ولو شعرة واحدة مع إكمال المسح على الخمار.',
      hanbali: 'يجوز المسح على خمار المرأة المدار تحت حلقها لمشقة نزعه في البرد والحاجة.',
      dalil: 'ثبوت مسح أم سلمة رضي الله عنها على خمارها.',
    ),
    FiqhItem(
      id: 'tahara_20',
      categoryId: 'tahara',
      question: 'هل لمس شعر المرأة أو رؤيته من قبل رجل أجنبي ينقض وضوءها هي؟',
      summary: 'رؤية الأجنبي لشعرها معصية بالغة ولكنها لا تنقض وضوءها باتفاق الأئمة الأربعة.',
      hanafi: 'كشف العورة ورؤيتها لا تنقض الوضوء.',
      maliki: 'لا ينتقض الوضوء بمجرد النظر أو كشف العورة.',
      shafii: 'نواقض الوضوء محددة وليس كشف الشعر منها.',
      hanbali: 'وضوؤها صحيح ولا ينتقض، وعليها التوبة وستر عورتها.',
      dalil: 'حصر الشارع لنواقض الوضوء في الخارج وزوال العقل والملامسة المخصوصة.',
    ),
    FiqhItem(
      id: 'tahara_21',
      categoryId: 'tahara',
      question: 'ما هي صفة الوضوء الكاملة الصحيحة للمرأة؟',
      summary: 'النية، البسملة، غسل الكفين ثلاثاً، المضمضة والاستنشاق ثلاثاً، غسل الوجه ثلاثاً، غسل اليدين للمرفقين ثلاثاً، مسح الرأس والأذنين، وغسل الرجلين للكعبين مع الترتيب والموالاة.',
      hanafi: 'النية سنة، والترتيب والموالاة سنن مؤكدة، وغسل الأعضاء الأربعة فرض.',
      maliki: 'الدلك والموالاة والنية فرائض في الوضوء.',
      shafii: 'النية والترتيب فرضان لا يصح الوضوء بدونهما مع الأعضاء الأربعة.',
      hanbali: 'التسمية واجبة مع الذكر، والترتيب والموالاة والنية أركان.',
      dalil: 'حديث عثمان بن عفان رضي الله عنه في صفة وضوء رسول الله ﷺ (متفق عليه).',
    ),
    FiqhItem(
      id: 'tahara_22',
      categoryId: 'tahara',
      question: 'ما هي أركان الوضوء التي لا يصح إلا بها؟',
      summary: 'الأركان الأربعة المتفق عليها بنص القرآن: غسل الوجه، غسل اليدين مع المرفقين، مسح الرأس، وغسل الرجلين مع الكعبين. وزاد الجمهور النية والترتيب والموالاة.',
      hanafi: 'الأركان 4 فقط المذكورة في آية المائدة.',
      maliki: 'الأركان 7: الأربعة القرآنية + النية + الدلك + الموالاة (الفور).',
      shafii: 'الأركان 6: الأربعة القرآنية + النية + الترتيب.',
      hanbali: 'الأركان 6: الأربعة القرآنية + الترتيب + الموالاة مع النية شرطاً.',
      dalil: 'قوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ﴾.',
    ),
    FiqhItem(
      id: 'tahara_23',
      categoryId: 'tahara',
      question: 'ما هي سنن الوضوء التي يُستحب فعلها لزيادة الأجر؟',
      summary: 'السواك، التسمية، غسل الكفين في البداية، المبالغة في المضمضة والاستنشاق لغير الصائم، تخليل الأصابع، مسح الأذنين، التيامن، التثليث، والدعاء بعده.',
      hanafi: 'السنن تشمل التسمية والمضمضة والاستنشاق والسواك ومسح الأذنين والرقبة.',
      maliki: 'غسل اليدين للكوعين، المضمضة، الاستنشاق، الاستنثار، رد مسح الرأس، ومسح الأذنين.',
      shafii: 'التسمية، السواك، التثليث، التيامن، إطالة الغرة والتحجيل، والذكر المأثور بعده.',
      hanbali: 'السواك، غسل الكفين ثلاثاً، المبالغة لغير الصائم، التيامن، وتخليل اللحية والأصابع.',
      dalil: 'قوله ﷺ: «من توضأ نحو وضوئي هذا ثم صلى ركعتين لا يحدّث فيهما نفسه غفر له ما تقدم من ذنبه».',
    ),
    FiqhItem(
      id: 'tahara_24',
      categoryId: 'tahara',
      question: 'ما هي مبطلات الوضوء (نواقضه)؟',
      summary: 'الخارج من السبيلين (بول، غائط، ريح، دم، إفرازات)، زوال العقل بنوم عميق أو إغماء، ومس الفرج ببطن الكف عند الجمهور.',
      hanafi: 'كل خارج نجس من السبيلين، والدم السائل من البدن، والقيء ملء الفم، والنوم مضطجعاً، والقهقهة في الصلاة.',
      maliki: 'الخارج المعتاد من السبيلين على وجه الصحة، وزوال العقل، ومس الفرج أو الالتذاذ بلمس.',
      shafii: 'الخارج من السبيلين، زوال العقل إلا نوم الممكن مقعدته، التقاء بشرتي أجنبيين، ومس الفرج.',
      hanbali: 'الخارج من السبيلين، الخارج النجس الكثير من البدن، زوال العقل، مس الفرج، وأكل لحم الإبل.',
      dalil: 'قوله ﷺ: «لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ».',
    ),
    FiqhItem(
      id: 'tahara_25',
      categoryId: 'tahara',
      question: 'متى يجوز للمرأة أن تتيمم بدلاً من الوضوء أو الغسل؟',
      summary: 'عند فقد الماء حقيقة، أو العجز عن استعماله لمرض يخشى معه زيادة العلة أو تأخر الشفاء، أو شدة برد مهلك لا يمكن معه تسخين الماء.',
      hanafi: 'يجوز عند البعد عن الماء ميلاً أو خوف المرض والبرد الشديد.',
      maliki: 'يجوز لعدم الماء أو خوف تلف نفس أو عضو أو زيادة مرض.',
      shafii: 'يجوز لفقد الماء طلباً، وللمرض المخوف، والحاجة للماء لعطش حيوان محترم.',
      hanbali: 'يجوز لعدم الماء أو خوف الضرر باستعماله أو خوف فوات الوقت عند عدم القدرة.',
      dalil: 'قوله تعالى: ﴿فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ﴾.',
    ),
    FiqhItem(
      id: 'tahara_26',
      categoryId: 'tahara',
      question: 'كيف تتيمم المرأة؟ وما هي صفة التيمم الصحيحة؟',
      summary: 'تنوي استباحة الصلاة، تضرب التراب الطاهر بيدها ضربة واحدة، فتمسح وجهها ثم كفيها وظاهرهما، وهو أصح ما ورد في السنة.',
      hanafi: 'ضربتان: ضربة للوجه وضربة لليدين مع المرفقين.',
      maliki: 'ضربة للوجه واليدين إلى الكوعين فرض، والمسح للمرفقين سنة مستحبة.',
      shafii: 'ضربتان بنقل التراب: ضربة للوجه وضربة لليدين إلى المرفقين مع النية المقترنة.',
      hanbali: 'ضربة واحدة يمسح بها وجهه وكفيه، وتجزئ ضربتان لليدين.',
      dalil: 'حديث عمار بن ياسر رضي الله عنه: «إنما كان يكفيك أن تصنع هكذا: فضرب بكفيه ضربة على الأرض ثم نفخهما فمسح بهما وجهه وكفيه» (متفق عليه).',
    ),
    FiqhItem(
      id: 'tahara_27',
      categoryId: 'tahara',
      question: 'ما حكم شرب المرأة دواء لتعجيل الحيضة عن وقتها؟',
      summary: 'جائز بشرط مأمنية الضرر الصحي بإشراف طبيب مختص، وإذا نزل الدم اعتبر حيضاً تسقط معه الصلاة والصوم، لكن تركه أفضل.',
      hanafi: 'جائز مع السلامة من الضرر والدم النازل حيض.',
      maliki: 'جائز للمصلحة ما لم يترتب عليه ضرر جسدي.',
      shafii: 'يباح تناول الدواء المباح لتنظيم أو تعجيل الحيض.',
      hanbali: 'يجوز شرب دواء مباح لإسقاط الحيض أو إنزاله ما لم يضر بصحتها.',
      dalil: 'القاعدة الشرعية: «لا ضرر ولا ضرار».',
    ),
    FiqhItem(
      id: 'salah_1',
      categoryId: 'salah',
      question: 'هل تختلف المرأة عن الرجل في كيفية الصلاة؟',
      summary: 'الأصل أن صلاة المرأة كصلاة الرجل في الأركان والشروط، ويستحب للمرأة الانضمام وضم الفخذين والذراعين في الركوع والسجود لأنه أستر لها.',
      hanafi: 'تضم المرأة بعضها لبعض في الركوع والسجود وتجلس متوركة على فخذها اليسرى.',
      maliki: 'تضم المرأة فخذيها وبطنها ولا تجافي ذراعيها في السجود ستراً لها.',
      shafii: 'تضم بعضها إلى بعض في الركوع والسجود وتسدل رجليها في الجلوس.',
      hanbali: 'تجمع نفسها وتضم بطنها إلى فخذيها في السجود والركوع لأنه أستر لها.',
      dalil: 'قول النبي ﷺ: «صلوا كما رأيتموني أصلي»، والآثار الواردة عن الصحابة في استحباب انضمام المرأة.',
    ),
    FiqhItem(
      id: 'salah_2',
      categoryId: 'salah',
      question: 'هل تصح صلاة المرأة بالبنطال؟',
      summary: 'تصح الصلاة مع الكراهة إن كان البنطال واسعاً ساتراً للون، وتشتد الكراهة إن كان ضيقاً يفصل تفاصيل العورة والأفضل ارتداء ثوب سابغ فضفاض.',
      hanafi: 'تصح مع الكراهة إن ستر لون البشرة، ومكروه تحريماً إن حدد العورة المغلظة.',
      maliki: 'تصح الصلاة مع الكراهة إن لم يشف الثوب عما تحته.',
      shafii: 'تصح الصلاة إن ستر اللون، وتكره الصلاة في الثوب المحدد والضيق.',
      hanbali: 'تصح الصلاة ما دام ساتراً للبشرة، ويستحب لها لبس درع سابغ وخمار واسع.',
      dalil: 'قوله تعالى: ﴿يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ﴾.',
    ),
    FiqhItem(
      id: 'salah_3',
      categoryId: 'salah',
      question: 'ماذا تفعل المرأة اذا انكشف شيء من جسدها حين الصلاة دون قصد؟',
      summary: 'إن سترته في الحال من غير تمادٍ صحت صلاتها عند الجمهور، وإن كان الانكشاف فاحشاً وطال زمنه بطلت الصلاة ووجبت إعادتها.',
      hanafi: 'تبطل الصلاة إذا انكشف ربع عضو واستمر قدر أداء ركن.',
      maliki: 'تصح إن كان الانكشاف خفيفاً أو سترته في الحين دون تأخير.',
      shafii: 'تصح إن سترته فوراً بغير عمل كثير، وإن طال بطلت الصلاة.',
      hanbali: 'تصح إن كان الانكشاف يسيراً أو غلبها فسترته في الحال بلا مهلة.',
      dalil: 'حديث عمرو بن سلمة في ستر العورة وتجاوز الشارع عن اليسير غير المتعمد.',
    ),
    FiqhItem(
      id: 'salah_4',
      categoryId: 'salah',
      question: 'حكم ظهور قدم المرأة في الصلاة؟',
      summary: 'الجمهور (المالكية والشافعية والحنابلة): قدما المرأة عورة في الصلاة يجب سترهما بثوب سابغ أو جوربين. الحنفية: قدما المرأة ليستا بعورة وتصح صلاتها مكشوفة القدمين.',
      hanafi: 'قدما المرأة ليستا بعورة في الصلاة وتصح صلاتها مكشوفة القدمين.',
      maliki: 'القدمان عورة في الصلاة وتعيد الصلاة في الوقت إن ظهرتا.',
      shafii: 'القدمان عورة تبطل الصلاة بكشفهما ويجب سترهما.',
      hanbali: 'ظاهر القدم وباطنها عورة في الصلاة وتبطل الصلاة بظهورهما.',
      dalil: 'حديث أم سلمة رضي الله عنها: تصلي المرأة في الدرع والخمار «إذا كان الدرع سابغاً يغطي ظهور قدميها».',
    ),
    FiqhItem(
      id: 'salah_5',
      categoryId: 'salah',
      question: 'هل تصح صلاتي بدون أذان أو إقامة؟',
      summary: 'تصح صلاة المرأة والمنفرد بدون أذان ولا إقامة باتفاق المذاهب الأربعة، ولا يجبان على النساء.',
      hanafi: 'لا يسن الأذان والإقامة للنساء وتصح صلاتهن دونهما.',
      maliki: 'تصح الصلاة بلا أذان ولا إقامة، ويكره الأذان للمرأة وتستحب الإقامة سراً.',
      shafii: 'يستحب للنساء الإقامة سراً ولا يسن لهن الأذان وتصح الصلاة بدونهما.',
      hanbali: 'لا يشرع الأذان والإقامة للمرأة وتصح صلاتها بدونهما إجماعاً.',
      dalil: 'أثر عائشة وابن عمر رضي الله عنهم: ليس على النساء أذان ولا إقامة.',
    ),
    FiqhItem(
      id: 'salah_6',
      categoryId: 'salah',
      question: 'هل يلزم انتظار انتهاء الأذان للدخول في الصلاة؟',
      summary: 'لا يلزم انتظار انتهاء الأذان للدخول في الصلاة، بل تصح فور تحقق دخول الوقت، ولكن يستحب إجابة المؤذن لنيل فضيلة الترديد والدعاء.',
      hanafi: 'تصح الصلاة بمجرد دخول الوقت دون اشتراط فراغ المؤذن.',
      maliki: 'تصح الصلاة فور سماع أول الأذان إن كان المؤذن يؤذن على الوقت.',
      shafii: 'يجوز الشروع في الصلاة مع بدء الأذان إذا تيقن دخول الوقت والانتظار أفضل.',
      hanbali: 'لا يشترط الفراغ من الأذان ويستحب الترديد والصلاة على النبي ﷺ.',
      dalil: 'قوله تعالى: ﴿إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَّوْقُوتًا﴾.',
    ),
    FiqhItem(
      id: 'salah_7',
      categoryId: 'salah',
      question: 'حكم إمامة المرأة لأولادها الصبيان في الصلاة لتعليمهم؟',
      summary: 'الجمهور: لا تصح إمامة المرأة للذكور ولو كانوا صبياناً في الفريضة، وجوزها الحنابلة في رواية والشافعية في النفل للتعليم.',
      hanafi: 'لا تصح إمامة المرأة للرجل ولا للصبي المميز مطلقاً.',
      maliki: 'لا تصح إمامة المرأة لذكر في فرض ولا نفل.',
      shafii: 'لا تصح إمامتها لذكر في الفريضة، وتصح في تعليم الصغير غير البالغ في النوافل.',
      hanbali: 'لا تصح إمامتها للرجال، وجوز بعض الأصحاب إمامتها في التراويح عند الحاجة.',
      dalil: 'قول النبي ﷺ: «لن يفلح قوم ولوا أمرهم امرأة»، وترتيب الصفوف بجعل النساء خلف الرجال.',
    ),
    FiqhItem(
      id: 'salah_8',
      categoryId: 'salah',
      question: 'هل تجوز الصلاة بجانب زوجي مباشرة لعدم وجود مساحة؟',
      summary: 'الجمهور: تصح صلاتهما مع الكراهة لمخالفة ترتيب الصفوف. الحنفية: تبطل صلاة الرجل إذا حاذته زوجته في صلاة مشتركة بشروطها.',
      hanafi: 'تبطل صلاة الرجل إذا حاذته المرأة في صلاة مطلقة متحدة الإمام والتحريمة.',
      maliki: 'تصح صلاة الرجل والمرأة مع الكراهة التنزيهية لضيق المكان.',
      shafii: 'تصح صلاة كل منهما مع فوات فضيلة الصفوف المشروعة.',
      hanbali: 'تصح الصلاة مع الكراهة، والأولى أن تقف خلفه ولو بخطوة يسيرة.',
      dalil: 'حديث أنس رضي الله عنه: «فصففت أنا واليتيم وراءه والعجوز من ورائنا».',
    ),
    FiqhItem(
      id: 'salah_9',
      categoryId: 'salah',
      question: 'ما حكم صلاة النساء في المسجد من الطابق الثاني؟',
      summary: 'صحيحة وجائزة باتفاق المذاهب إذا كنّ يقتدين بالإمام ويسمعن تكبيراته وتتصل الصفوف حكماً داخل المسجد الواحد.',
      hanafi: 'تصح صلاتهن ما دام الجامع مسجداً واحداً وتسمع التكبير.',
      maliki: 'تصح الصلاة مع سماع الإمام داخل سور المسجد وأروقته.',
      shafii: 'تصح صلاة المأموم في المسجد في أي طابق إذا علم بانتقالات الإمام.',
      hanbali: 'تصح صلاة المأموم في جميع أجزاء المسجد وعلوله مع سماع التكبير.',
      dalil: 'إجماع الأئمة على صحة اقتداء من في المسجد بالإمام مع سماع الصوت.',
    ),
    FiqhItem(
      id: 'salah_10',
      categoryId: 'salah',
      question: 'ما حكم مرور المرأة أمام المرأة في الصلاة؟',
      summary: 'المرور أمام المصلي مكروه وينقص الأجر ولا يبطل الصلاة عند الأئمة الأربعة.',
      hanafi: 'المرور لا يفسد الصلاة ويأثم المار بين يدي المصلي دون سترة.',
      maliki: 'لا تبطل الصلاة بمرور امرأة أو غيرها ويكره المرور.',
      shafii: 'لا يقطع الصلاة شيء من المارين وتكره المجاوزة قريباً من المصلي.',
      hanbali: 'الصلاة صحيحة ولا يقطعها مرور امرأة عند الجمهور، وأخذ بعضهم بقطع مرور المرأة البالغة.',
      dalil: 'قول النبي ﷺ: «لا يقطع الصلاة شيء وادرأوا ما استطعتم».',
    ),
    FiqhItem(
      id: 'salah_11',
      categoryId: 'salah',
      question: 'حكم جمع الصلاة للعروس يوم الزفاف؟',
      summary: 'الجمهور يمنعون الجمع لغير الأعذار المعروفة، وأجازه الحنابلة للحاجة والمشقة الشديدة تقديماً أو تأخيراً بين الظهر والعصر أو المغرب والعشاء.',
      hanafi: 'لا يجوز الجمع إلا بعرفة ومزدلفة فقط للحاج.',
      maliki: 'يجوز الجمع للسفر والمطر والمرض المشق دون الأعراس.',
      shafii: 'يجوز الجمع في السفر والمطر ولا يجوز للزفاف في المعتمد.',
      hanbali: 'يجوز الجمع للحاجة والمشقة الشديدة ما لم يتخذه عادة دفعاً للحرج.',
      dalil: 'حديث ابن عباس رضي الله عنهما: «جمع رسول الله ﷺ بالمدينة بين الظهر والعصر والمغرب والعشاء من غير خوف ولا مطر، قيل: ما أراد بذلك؟ قال: أراد ألا يحرج أمته».',
    ),
    FiqhItem(
      id: 'salah_12',
      categoryId: 'salah',
      question: 'ما حكم الصلاة التي دخل وقتها ثم حاضت المرأة قبل أن تؤديها؟',
      summary: 'الحنفية والمالكية: تسقط ولا يلزم قضاؤها. الشافعية والحنابلة: يلزم قضاؤها بعد الطهر إن كانت أدركت من الوقت زمناً يسع الطهارة وركعات الصلاة وتراخت.',
      hanafi: 'تسقط ولا قضاء عليها؛ لأن الوجوب يستقر بآخر الوقت.',
      maliki: 'تسقط ولا قضاء عليها إلا إن كانت مفرطة تفريطاً واضحاً.',
      shafii: 'يجب قضاؤها بعد الطهر لأن الصلاة وجبت بدخول وقتها وقدرتها على الفعل.',
      hanbali: 'يجب قضاؤها إن أدركت زمناً يسع تكبيرة الإحرام قبل نزول الدم.',
      dalil: 'استقرار الدين في الذمة ببلوغ وقت الخطاب والتمكن منه.',
    ),
    FiqhItem(
      id: 'salah_13',
      categoryId: 'salah',
      question: 'حكم الإسراع في أداء الصلاة انشغالاً بالأولاد والبيت؟',
      summary: 'الإسراع الذي يسقط معه ركن الطمأنينة يبطل الصلاة باتفاق العلماء، وأما التخفيف مع الحفاظ على الأركان والواجبات فجائز ومسنون.',
      hanafi: 'الطمأنينة واجبة عند أبي حنيفة وركن عند الصاحبين وتبطل الصلاة بنقرها.',
      maliki: 'الطمأنينة ركن تبطل الصلاة بتركه عمداً أو سهواً.',
      shafii: 'الطمأنينة في الركوع والسجود والاعتدال ركن لا تصح الصلاة بدونه.',
      hanbali: 'الطمأنينة ركن، وتخفيف القراءة للضرورة مستحب كبكاء الصبي.',
      dalil: 'قول النبي ﷺ للمسيء صلاته: «ارجع فصل فإنك لم تصل» لتركه الطمأنينة.',
    ),
    FiqhItem(
      id: 'salah_14',
      categoryId: 'salah',
      question: 'ما حكم جلوس المرأة في الصلاة بسبب بكاء رضيعها؟',
      summary: 'القيام ركن في صلاة الفريضة للقادر عليه، ولا يجوز الانتقال للجلوس بمجرد بكاء الرضيع بل تخفف الصلاة وتتمها قائمة ثم تنصرف إليه.',
      hanafi: 'القيام فرض في المكتوبة وتبطل صلاة القادر إن جلس بلا عذر مرضي.',
      maliki: 'الجلوس يبطل الفريضة مع القدرة على القيام.',
      shafii: 'القيام ركن للقادر وتبطل الصلاة بتركه لغير عذر مسقط للقيام.',
      hanbali: 'لا يجوز الجلوس في الفرض للقادر، وتخفف القراءة والأذكار وتسلم سريعاً.',
      dalil: 'قوله تعالى: ﴿وَقُومُوا لِلَّهِ قَانِتِينَ﴾، وقوله ﷺ: «صل قائماً فإن لم تستطع فقاعداً».',
    ),
    FiqhItem(
      id: 'salah_15',
      categoryId: 'salah',
      question: 'حكم إرضاع المرأة طفلها في الصلاة؟',
      summary: 'الحركة الكثيرة المتوالية تبطل الصلاة بالإجماع، فإن كان الرضاع يحتاج إلى كشف عورة أو حركة كثيرة أفسد الصلاة، ولها قطعها للضرورة وإعادتها.',
      hanafi: 'يبطل الصلاة لكثرة العمل وكشف العورة وابتلاع اللبن.',
      maliki: 'يبطل الصلاة إن كثر الفعل واستدبرت القبلة أو انكشفت العورة.',
      shafii: 'الفعل الكثير المتوالي من غير جنس الصلاة يبطلها قطعاً.',
      hanbali: 'تبطل الصلاة بالعمل الكثير عرفاً، ويجوز قطع الصلاة لإنقاذ الصغير.',
      dalil: 'نهي الشريعة عن العبث والعمل الكثير المنافي لهيئة الصلاة.',
    ),
    FiqhItem(
      id: 'salah_16',
      categoryId: 'salah',
      question: 'كيفية التنبيه في حق النساء إذا حصل لهن خلل في الصلاة؟',
      summary: 'التصفيق (التصفيح) للنساء بضرب باطن الكف على ظهر اليد الأخرى، والتسبيح للرجال لقوله ﷺ: «التسبيح للرجال والتصفيق للنساء».',
      hanafi: 'تصفح المرأة ببطن كفها على ظهر الأخرى وتكره بالجهر بالصوت.',
      maliki: 'تصفق المرأة ولا تسبح جهراً بحضرة الرجال.',
      shafii: 'تصفق ببطن كف على ظهر الأخرى ولا تضرب بطناً ببطن لعباً.',
      hanbali: 'السنة للنساء التصفيح ببطن كفها اليمنى على ظهر كفها اليسرى.',
      dalil: 'حديث أبي هريرة رضي الله عنه في الصحيحين: «التسبيح للرجال والتصفيق للنساء».',
    ),
    FiqhItem(
