      categoryId: 'salah',
      question: 'ما حكم صلاة المرأة جالسة في مكان عام لوجود الرجال؟',
      summary: 'لا يجوز ترك القيام في الفريضة حياءً من الرجال، بل تصلي قائمة في أستر موضع ممكن وتتحجب حجاباً كاملاً، فالقيام ركن مفروض.',
      hanafi: 'القيام فرض لا يسقط برؤية الأجانب ما دامت مستترة.',
      maliki: 'تبطل صلاتها جالسة مع القدرة على القيام.',
      shafii: 'لا يجوز الجلوس في الفريضة وتتحرى مكاناً آمناً ساتراً.',
      hanbali: 'القيام ركن لا يسقط إلا بالعجز الحقيقي أو الخوف المحقق.',
      dalil: 'قوله ﷺ: «صل قائماً فإن لم تستطع فقاعداً».',
