      categoryId: 'salah',
      question: 'حكم ترك الصلاة بعد بلوغها ظناً منها أنها ما زالت صغيرة؟',
      summary: 'يجب عليها قضاء جميع الصلوات التي تركتها من تاريخ بلوغها الحقيقي بالحيض أو الاحتلام أو السن مع التوبة الصادقة.',
      hanafi: 'الصلوات المتروكة دين في الذمة يجب قضاؤها بحسب الاستطاعة.',
      maliki: 'يجب قضاء الفوائت وترتيبها مع التوبة والاستغفار.',
      shafii: 'يجب قضاء كل فريضة تركتها بعد سن البلوغ الشرعي فوراً.',
