      summary: 'لا تصح الصلاة بالملابس الشفافة التي تصف لون البشرة باتفاق الأئمة الأربعة؛ لأن ستر العورة شرط صحة بإجماع المسلمين.',
      hanafi: 'يشترط ساتر يمنع إدراك لون البشرة وتبطل الصلاة بالشفاف.',
