      question: 'ماذا تفعل إذا انكشف جزء من ساعدها (الذراع)؟',
      summary: 'تستره فوراً وتكمل صلاتها إن كان يسيراً أو عارضاً، فإن تعمدت كشفه أو طال انكشافه بطلت صلاتها عند الجمهور.',
      hanafi: 'إن انكشف أقل من ربع الساعد صحت، وإن زاد واستمر ركناً بطلت.',
      maliki: 'تستره فوراً ولا تفسد الصلاة بالانكشاف الخفيف الطارئ.',
      shafii: 'تبطل الصلاة إن لم تستره في الحال بغير عمل كثير.',
      hanbali: 'يعفى عن اليسير الذي ينكشف ثم يستر في الحال بلا توانٍ.',
      dalil: 'قاعدة: «المشقة تجلب التيسير» والعفو عن الخطأ غير المتعمد.',
