      summary: 'تأخذ حكم أصحاب الأعذار: تتوضأ بعد دخول وقت كل صلاة، وتصلي الفريضة وما شاءت من النوافل ولا يضرها ما خرج بعد ذلك.',
      hanafi: 'تتوضأ لوقت كل صلاة وتصلي ما شاءت في الوقت.',
      maliki: 'تتوضأ استحباباً ولا يبطل وضوؤها بالحدث المستنكح ما لم ينقطع زمناً كافياً.',
      shafii: 'تتوضأ لكل فريضة بعد دخول وقتها مع التحفظ.',
      hanbali: 'تتوضأ لدخول وقت كل صلاة وتصلي الفرض والنوافل.',
      dalil: 'حديث النبي ﷺ لحمنة وفاطمة في حكم المستحاضة وأصحاب السلس.',
    ),
    FiqhItem(
      id: 'salah_23',
      categoryId: 'salah',
      question: 'ماذا عن الضحك والتبسم أثناء الصلاة؟',
      summary: 'التبسم لا يبطل الصلاة باتفاق العلماء. والضحك بصوت (القهقهة) يبطل الصلاة بإجماع العلماء، وينقض الوضوء عند الحنفية في الصلاة التامة.',
      hanafi: 'القهقهة تبطل الصلاة وتنقض الوضوء في كل صلاة ذات ركوع وسجود.',
      maliki: 'الضحك يبطل الصلاة ولا ينقض الوضوء، والتبسم لا يضر.',
      shafii: 'الضحك بصوت يبطل الصلاة لظهور حرفين فأكثر ولا ينقض الوضوء.',
      hanbali: 'القهقهة تبطل الصلاة إجماعاً ولا تنقض الوضوء خارج الصلاة.',
      dalil: 'إجماع الأمة على بطلان الصلاة بالضحك المسموع.',
    ),
    FiqhItem(
