      shafii: 'يسجد للسهو قبل السلام عند الشافعية في كل سهو.',
      hanbali: 'يسجد للسهو بعد السلام إذا زاد في صلاته سهواً.',
      dalil: 'حديث ابن مسعود رضي الله عنه أن النبي ﷺ صلى خمساً فسجد سجدتي السهو بعدما سلم.',
    ),
