      summary: 'الصلاة صحيحة مع الكراهة التنزيهية إن كانت الصور لذوات الأرواح معلقة أمام المصلي لتشويشها ولنهي الملائكة عن دخول بيت فيه صورة.',
      hanafi: 'تكره الصلاة في مكان فيه تصاوير ذوات الأرواح والصلاة صحيحة.',
