      dalil: 'قوله ﷺ لعائشة في الخمار الموشى: «أميطي عنا قرامك هذا فإنه لا تزال تصاويره تعرض لي في صلاتي».',
    ),
    FiqhItem(
      id: 'salah_27',
      categoryId: 'salah',
      question: 'حكم من سالت أنفها دمًا (رعاف) في الصلاة؟',
      summary: 'إن كان يسيراً تمسحه وتتم، وإن كان كثيراً استدبرت القبلة وخرجت لغسله وتستأنف الوضوء والصلاة عند الجمهور، وعند الحنفية والمالكية تبني على ما مضى بشروط.',
      hanafi: 'تخرج وتغسل الدم وتبني على ما صلت ما لم تتكلم.',
      maliki: 'تبني على صلاتها إن لم تطل المدة ولم تتلوث بالنجاسة.',
      shafii: 'ينتقض الوضوء بالخارج النجس إن كان كثيراً وتستأنف الصلاة من أولها.',
      hanbali: 'إن كان الدم يسيراً تمسحه وتتم، وإن كثر بطل الوضوء والصلاة.',
      dalil: 'حديث عائشة رضي الله عنها في بناء الراعف على صلاته ما لم يتكلم.',
    ),
