      question: 'على من يجب صيام رمضان ؟',
      summary: 'يجب صيام رمضان على كل مسلم، بالغ، عاقل، مقيم، قادر على الصوم، خالٍ من الموانع الشرعية كالمرأة في الحيض والنفاس.',
