    FiqhItem(
      id: 'siyam_3',
      categoryId: 'siyam',
      question: 'ما شروط صحة الصيام ؟',
      summary: 'النية الجازمة من الليل لكل يوم (أو للشهر كله عند المالكية)، والنقاء التام من دم الحيض والنفاس، والتمييز، والعقل طوال جزء من النهار.',
