      maliki: 'النية قبل الفجر والنقاء من الحيض والنفاس طوال النهار.',
      shafii: 'النية المبيتة لكل ليلة في الفرض والنقاء من الحيض والنفاس.',
      hanbali: 'النية وتبييتها من الليل والإمساك عن المفطرات والنقاء الشرعي.',
      dalil: 'قوله ﷺ: «من لم يبيت الصيام من الليل فلا صيام له».',
