    FiqhItem(
      id: 'siyam_4',
      categoryId: 'siyam',
      question: 'هل الطهارة شرطاً لصحة الصوم ؟',
      summary: 'الطهارة من الحدث الأصغر والأكبر كالجنابة ليست شرطاً لصحة الصوم بالإجماع، فمن أصبح جنباً فصومه صحيح ويغتسل للصلاة. أما الطهارة من الحيض قبل الفجر فشرط لصحة صوم ذلك اليوم.',
      hanafi: 'صوم الجنب صحيح ويغتسل لصلاته إجماعاً.',
      maliki: 'تصح صوم الجنب وتغتسل بعد طلوع الفجر.',
      shafii: 'الصوم صحيح وتأخير الغسل لما بعد الفجر لا يبطله.',
      hanbali: 'الصيام صحيح بالإجماع لحديث عائشة وأم سلمة.',
      dalil: 'حديث عائشة وأم سلمة: «كان رسول الله ﷺ يدركه الفجر وهو جنب من أهله ثم يغتسل ويصوم» (متفق عليه).',
    ),
    FiqhItem(
      id: 'siyam_5',
      categoryId: 'siyam',
      question: 'هل يجوز ذوق الطعام أثناء الصيام ؟',
      summary: 'يكره لغير حاجة، ويجوز للحاجة كالطاهية والأم بشرط ألا تبتلع منه شيئاً وتمجه من فمها باتفاق المذاهب الأربعة.',
      hanafi: 'يكره ذوق الطعام وتصح الصوم إن مجته ولم تبتلعه.',
      maliki: 'يكره للعامة ويرخص فيه للطاهي والمشتري دون ابتلاع.',
      shafii: 'مكروه لغير حاجة وجائز للحاجة مع مجّه ولا يفطر ما لم يصل للحلق.',
      hanbali: 'يجوز ذوق الطعام للحاجة كإصلاح قدر الطعام ولا يفسد الصوم.',
      dalil: 'أثر ابن عباس رضي الله عنهما: «لا بأس أن يذوق الخل أو الشيء ما لم يدخل حلقه وهو صائم».',
