    FiqhItem(
      id: 'siyam_6',
      categoryId: 'siyam',
      question: 'إذا أكل الصائم ظاناً غروب الشمس أو عدم طلوع الفجر، ثم تبين خلاف ظنه.. هل يقضي؟',
      summary: 'الجمهور (الحنفية والمالكية والشافعية والحنابلة في المشهور): يجب عليه قضاء ذلك اليوم لعدم تمام الصوم نهاراً. واختار ابن تيمية عدم القضاء للعذر بالخطأ.',
      hanafi: 'يجب عليه القضاء فقط ولا كفارة عليه لعدم العمد.',
      maliki: 'يجب القضاء لحصول الإفطار نهاراً في الواقع.',
      shafii: 'يجب القضاء لتبين وقوع الأكل في جزء من النهار المفروض.',
      hanbali: 'المعتمد وجوب القضاء، ورواية أخرى لا قضاء عليه لرفع الحرج والخطأ.',
      dalil: 'قوله تعالى: ﴿ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ﴾ وتفريط المكلف في التحري.',
    ),
