      shafii: 'الكفارة على الرجل فقط وعليها القضاء مطلقاً.',
      hanbali: 'تلزمها الكفارة إن كانت مطاوعة وتسقط بالإكراه.',
      dalil: 'حديث الجماع في رمضان وعموم الخطاب في الكفارات للزاجر والمكلف.',
