      summary: 'التوبة النصوح الصادقة، والمبادرة بقضاء ما أفطرته بحسب استطاعتها مع إخراج الفدية عن كل يوم تأخر قضاؤه عند الجمهور.',
      hanafi: 'يجب قضاء جميع الأيام بالتتابع أو التفريق مع التوبة.',
