      summary: 'تسقط عند الشافعية في قول إن عجز عنها كلياً بفقره ومرضه، وتبقى ديناً في ذمته عند الجمهور يؤديها متى استطاع.',
      hanafi: 'تبقى في ذمته حتى يوسر ويستطيع الأداء.',
      maliki: 'تستقر ديناً في الذمة ولا تسقط بالعجز المؤقت.',
      shafii: 'تسقط إن عجز عن المراتب الثلاث وقت الوجوب في الأصح.',
      hanbali: 'تبقى في ذمته يؤديها متى تيسرت له أسبابها.',
      dalil: 'حديث الأعرابي حين قال: ما بين لابتيها أهل بيت أفقر منا، فقال ﷺ: «أطعمه أهلك».',
