      question: 'إذا صامت المرأة وهي حامل وعليها نزيف هل يصح الصوم ؟',
      summary: 'إن كان نزيف حمل طبياً وليس دم عادة فصيامها صحيح، ويجوز لها الفطر إن خافت على صحتها أو صحة جنينها وتقضي بعد ذلك.',
      hanafi: 'دم الحمل استحاضة وفساد لا يبطل الصوم.',
      maliki: 'الحامل قد تحيض عند المالكية فإن كان دم عادة أفطرت وإن كان نزيفاً صامت.',
      shafii: 'دم النزيف أثناء الحمل لا يفسد الصوم وتصوم وتصلي.',
      hanbali: 'الصوم صحيح إن لم يكن دم عادة مستقرة ولها الفطر للعذر الطبي.',
      dalil: 'حديث النبي ﷺ في وضع الصوم عن الحامل والمرضع عند المشقة.',
    ),
    FiqhItem(
