      categoryId: 'siyam',
      question: 'عليّ قضاء أيام منذ بلوغي، لكن نسيت عدد أيامها، والآن أصوم من عام بلوغي في كل عام ستة أيام، مع إخراج فدية عن كل يوم، هل ما أقوم به صحيح ؟',
      summary: 'عملها صحيح ومبارك، وتستمر حتى تطمئن أنها استوفت جميع الأيام التي أفطرتها مع الفدية المخرجة عن التأخير.',
      hanafi: 'فعلها حسن ومجزئ حتى يغلب على ظنها القضاء التام.',
      maliki: 'تصرف صحيح وتبرأ به الذمة تدريجياً.',
      shafii: 'عمل مشروع وتستمر فيه حتى تتيقن استيفاء الفوائت.',
      hanbali: 'صحيح ومثاب عليه وتتابع حتى تغلب براءة الذمة.',
      dalil: 'قوله تعالى: ﴿فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ﴾.',
    ),
    FiqhItem(
