      categoryId: 'siyam',
      question: 'ما هو الفرق الفقهي بين الكفارة والفدية ؟',
      summary: 'الكفارة: زجر وعقوبة مشددة لارتكاب محظور كالجماع في رمضان (عتق، فصيام شهرين، فإطعام 60 مسكيناً). الفدية: عوض وبدل مالي ميسر لعذر دائم كالهرم والمرض المزمن (إطعام مسكين عن كل يوم).',
      hanafi: 'الكفارة جزاء جناية مرتبة، والفدية بدل طاعة لعاجز.',
      maliki: 'الكفارة فيها التغليظ، والفدية رخصة وتيسير للمريض الهرم.',
      shafii: 'الكفارة تترتب على هتك حرمة الصوم، والفدية تترتب على العجز وفوات الوقت.',
      hanbali: 'الفروق ظاهرة في السبب والمقدار والمصرف بين الكفارات والفدى.',
      dalil: 'نصوص القرآن في التمييز بين كفارة الظهار والجماع وبين فدية طعام مسكين.',
    ),
    FiqhItem(
