      categoryId: 'siyam',
      question: 'ما حكم من مات وعليه قضاء صيام ؟',
      summary: 'يستحب لوليه وقريبه أن يصوم عنه لحديث: «من مات وعليه صيام صام عنه وليه»، ويجوز إخراج فدية إطعام مسكين عن كل يوم من تركته باتفاق الأئمة.',
      hanafi: 'يطعم عنه وليه من تركته عن كل يوم نصف صاع ولا يصام عنه.',
      maliki: 'يطعم عنه ولا يصام عنه في المعتمد وتجوز الصدقة.',
      shafii: 'يسن للولي أن يصوم عنه ويجوز الإطعام عنه مداً لكل يوم.',
      hanbali: 'يصوم عنه وليه ندباً في النذر والقضاء أو يطعم مسكيناً عن كل يوم.',
      dalil: 'حديث عائشة وابن عباس في الصحيحين: «من مات وعليه صيام صام عنه وليه».',
    ),
