      question: 'هل يجوز للزوجة أن تسقط الشرط الذي شرطه وليها في العقد ؟',
      summary: 'نعم، إذا كان الشرط لحقها ومنفعتها الخاصة (كالمهر أو السكن أو العمل) جاز لها إسقاطه برضاها واختيارها التام.',
      hanafi: 'يجوز لها التنازل عن حقها الخالص بعد العقد.',
      maliki: 'الحق لها فيجوز لها إسقاطه والعفو عنه.',
      shafii: 'كل شرط لمنفعة الزوجة تملك إسقاطه باختيارها.',
      hanbali: 'يجوز للمرأة إسقاط شروطها وحقوقها المالية ما دامت راشدة.',
      dalil: 'قوله تعالى: ﴿فَإِن طِبْنَ لَكُمْ عَن شَيْءٍ مِّنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَّرِيئًا﴾.',
    ),
    FiqhItem(
