      categoryId: 'marriage',
      question: 'حكم اشتراط عدم التعدد على الزوج ؟',
      summary: 'صحيح وملزم عند الحنابلة (وهو المعتمد في المحاكم الحديثة)، فإن تزوج عليها فلها حق طلب الطلاق وفسخ النكاح واستيفاء كامل حقوقها.',
      hanafi: 'الشرط لاغٍ والعقد صحيح ولا يمنعه من التعدد.',
      maliki: 'الشرط مكروه ولا يبطل العقد وتلغو فائدته عند المالكية.',
      shafii: 'الشرط باطل والعقد صحيح في الأظهر عند الشافعية.',
      hanbali: 'الشرط صحيح وملزم للزوج؛ فإن تزوج عليها فلها الخيار في فسخ النكاح واسترداد حقوقها.',
      dalil: 'قول النبي ﷺ: «إن أحق الشروط أن توفوا به ما استحللتم به الفروج» وتأكيد الصحابة كعمر بن الخطاب رضي الله عنه.',
    ),
    FiqhItem(
      id: 'marriage_29',
      categoryId: 'marriage',
      question: 'حكم اشتراط الزوجة الثانية طلاق الزوجة الأولى ؟',
      summary: 'محرم وباطل شرعاً بنهي النبي ﷺ الصريح: «لا تسأل المرأة طلاق أختها لتكفأ ما في إنائها ولتنكح فإنما لها ما قدر لها».',
      hanafi: 'شرط باطل محرم لا يحل للزوج الوفاء به.',
      maliki: 'حرام وباطل شرعاً ولا عبرة به.',
      shafii: 'الشرط ملغى باطل لمخالفته النص الصريح.',
      hanbali: 'باطل ومحرم ولا يجوز للزوج طلاق الأولى لأجل هذا الشرط الفاسد.',
      dalil: 'حديث أبي هريرة في الصحيحين: «لا تسأل المرأة طلاق أختها لتكفأ ما في صحفتها».',
