      summary: 'وصل الشعر بشعر آدمي أو طبيعي محرم وكبيرة من الكبائر لحديث «لعن الله الواصلة والمستوصلة»، ورخص بعض الفقهاء في الخيوط والصوف والحرير للزينة دون تدليس.',
      hanafi: 'يحرم وصل الشعر بشعر آدمي، ويباح بالصوف والخيوط للزوج.',
      maliki: 'يحرم الوصل بالشعر مطلقاً ولو بإذن الزوج.',
      shafii: 'يحرم وصل الشعر بشعر نجس أو شعر آدمي، ويجوز بشعر طاهر للزوج.',
      hanbali: 'محرم بلعن الشارع للواصلة والمستوصلة ويباح ما كان من غير الشعر كالشرائط.',
      dalil: 'حديث أسماء وأبي هريرة في الصحيحين: «لعن رسول الله ﷺ الواصلة والمستوصلة».',
    ),
    FiqhItem(
      id: 'marriage_32',
      categoryId: 'marriage',
      question: 'الأخذ من الحاجبين وإزالة شعر الوجه..المباح والممنوع ؟',
      summary: 'النمص (نتف شعر الحاجبين وتدقيقهما) محرم، ويباح إزالة شعر الوجه والشارب واللحية المشوه للمرأة، والشعر الزائد بين الحاجبين.',
      hanafi: 'يحرم النمص لغير المتزوجة، وتأخذ المتزوجة ما يشوه بإذن زوجها.',
      maliki: 'النمص محرم، وتجوز إزالة شعر اللحية والشارب والعارضين.',
      shafii: 'يحرم النمص إلا إذا نبت للمرأة لحية أو شارب فيسن إزالتهما.',
      hanbali: 'النمص نتف شعر الحاجبين محرم، ويباح تنظيف ما بين الحاجبين والوجه.',
      dalil: 'حديث ابن مسعود رضي الله عنه: «لعن الله الواشمات والمستوشمات والنامصات والمتنمصات المغيرات خلق الله».',
    ),
    FiqhItem(
