      question: 'حكم إزالة الشعر الزائد بالليزر في مراكز التجميل ؟',
      summary: 'يجوز للمرأة بالليزر في الوجه واليدين والساقين، ويحرم كشف العورة المغلظة (السوأتين) أمام الطبيبة إلا لضرورة أو علاج طبي يتعين فيه ذلك.',
