      shafii: 'يحرم كشف العورة لغير علاج ومرض متعين.',
      hanbali: 'يجوز استخدام الليزر الذاتي أو كشف ما سوى العورة المغلظة.',
      dalil: 'قوله ﷺ: «لا ينظر الرجل إلى عورة الرجل ولا المرأة إلى عورة المرأة» (رواه مسلم).',
