      question: 'حكم ثقب السرة والشفاه وغيرها للزينة ؟',
      summary: 'ثقب الأذن مباح للزينة بالإجماع، وثقب الأنف جائز للعرف، أما ثقب السرة والشفاه فمكروه أو محرم عند عامة الفقهاء لما فيه من المثلة وتشويه البدن والتشبه بغير المسلمين.',
      hanafi: 'ثقب الأذن جائز وثقب غيرها مكروه وفيه إيلام بلا مصلحة شرعية.',
      maliki: 'المباح ما جرى به عرف نساء المسلمين كثقب الأذن.',
      shafii: 'جائز في الأذن ومكروه في غيرها لعدم الحاجة وخوف الضرر.',
      hanbali: 'مباح في الأذن للقرط، وممنوع في الشفاه والسرة للتشبه والإيلام.',
      dalil: 'حديث أم زرع في إكرام أبي زرع لها بالحلي والأقراط في أذنيها.',
