    FiqhItem(
      id: 'marriage_50',
      categoryId: 'marriage',
      question: 'حكم نوم الزوجة في غرفة غير التي ينام فيها زوجها؟',
      summary: 'إن كان برضاه ولعذر كمرض أو راحة فلا حرج، وإن كان هجراناً له وإعراضاً عن حقه بغير رضاه فهو محرم وتأثم به.',
