      maliki: 'لا يجوز الهجران المضر بالزوج إلا لعذر مبيح.',
      shafii: 'يحرم ترك فراش الزوجية إن أدى لتفويت حقه المشروع.',
      hanbali: 'تأثم إن قصدت الإضرار به وهجره بغير إذنه ورضاه.',
      dalil: 'قول النبي ﷺ: «إذا دعا الرجل امرأته إلى فراشه فأبت فبات غضبان عليها لعنتها الملائكة حتى تصبح» (متفق عليه).',
    ),
