      summary: 'نعم، يحق للزوجة مطالبة زوجها بالعودة إن غاب أكثر من 6 أشهر وتضررت بغيابه وخافت على نفسها الفتنة، عملاً بقضاء عمر بن الخطاب رضي الله عنه.',
