      shafii: 'النفقة فرض على الزوج وحده ولا تجبر الزوجة على دفع شيء.',
      hanbali: 'النفقة واجبة على الرجل، ومساهمة الزوجة صدقة وبر وتطوع.',
      dalil: 'قوله تعالى: ﴿الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَا أَنفَقُوا مِنْ أَمْوَالِهِمْ﴾.',
    ),
