      question: 'إقامة زوجك في منزلك الخاص..هل تُسقط قوامته ؟',
      summary: 'لا تسقط القوامة؛ فالقوامة حق شرعي جعله الله للرجل لقيادة الأسرة والنفقة، وسكنه في بيتها برضاها فضل منها وتبرع لا يسقط واجب طاعته في المعروف.',
      hanafi: 'القوامة ثابتة بعقد النكاح والشرع.',
      maliki: 'لا تسقط القوامة بكون المسكن ملكاً للزوجة.',
      shafii: 'القوامة تكليف شرعي لا يسقطه التبرع بالمسكن.',
      hanbali: 'يبقى الزوج قيماً ورباً للأسرة مع شكر فضل الزوجة وإحسانها.',
      dalil: 'قوله تعالى: ﴿الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ﴾.',
    ),
    FiqhItem(
