      categoryId: 'marriage',
      question: 'زوجك المسافر هل تحتاجين إذنه في كل خطوة.. اكتشفي',
      summary: 'الأمور المعتادة اليومية (كشراء الحاجيات والمدارس وزيارة الأهل المأذون فيها عرفاً) تجوز بالإذن العام العرفي، وما استجد من أسفار وخروج غير معتاد يستأذن فيه.',
      hanafi: 'الإذن العرفي والضمني كافٍ في التصرفات المعتادة.',
      maliki: 'يكفي الإذن العام في الخروج المعتاد للبيت والمصالح.',
      shafii: 'الحاجة اليومية تنزل منزلة الإذن الصريح.',
      hanbali: 'تستأذن في الأمور الكبيرة والأسفار ويكفي الإذن العرفي في المعاش اليومي.',
      dalil: 'قاعدة: «المعروف عرفاً كالمشروط شرطاً».',
    ),
    FiqhItem(
      id: 'marriage_67',
      categoryId: 'marriage',
      question: 'هجرني بلا عذر..فهل يحق له ذلك ؟',
      summary: 'لا يحل للزوج هجر زوجته في الفراش أو الكلام بلا نشوز ولا مسوغ شرعي، ولا يجوز أن يزيد الهجر على أربعة أشهر (حكم الإيلاء) فإن زاد فلها حق طلب الطلاق والفسخ.',
      hanafi: 'يحرم الهجر بغير نشوز ولا يتجاوز 4 أشهر.',
      maliki: 'الهجر الظالم محرم ويسقط حقه في الطاعة.',
      shafii: 'يحرم الهجر لغير سبب شرعي ويثبت لها حق الفسخ عند الضرر.',
      hanbali: 'لا يجوز هجرها فوق 4 أشهر إلا برضاها ويثبت لها حق طلب الطلاق لدفع الضرر.',
      dalil: 'قوله تعالى: ﴿لِّلَّذِينَ يُؤْلُونَ مِن نِّسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِن فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ﴾.',
    ),
    FiqhItem(
      id: 'marriage_68',
      categoryId: 'marriage',
      question: 'أرفض الإنجاب من أجل العمل ..هل أكون آثمة ؟',
      summary: 'نعم، تأثم إن امتنعت من الإنجاب كلياً أو بغير رضا زوجها لمجرد العمل؛ لأن الإنجاب وحفظ النسل حق مشترك للزوجين ومقصد أعظم من مقاصد الزواج.',
      hanafi: 'حق الولد مشترك ولا يجوز قطعه بغير تراضٍ.',
      maliki: 'يحرم منع الحمل الدائم أو المؤقت بغير عذر ورضا الزوج.',
      shafii: 'الإنجاب حق للزوج لا تملك الزوجة إسقاطه من جانب واحد.',
      hanbali: 'تأثم إن حرمت زوجها من الذرية بغير رضاه وعذر شرعي معتبر.',
      dalil: 'قول النبي ﷺ: «تزوجوا الودود الولود فإني مكاثر بكم الأمم يوم القيامة».',
    ),
    FiqhItem(
      id: 'marriage_69',
      categoryId: 'marriage',
      question: 'هجرت الفراش بسبب عجزه عن النفقة.. فهل أنا آثمة ؟',
      summary: 'إن كان الزوج معسراً عاجزاً عن النفقة فلها طلب الفسخ والطلاق عند القاضي، ولا يحل لها البقاء في عصمته مع هجره عمداً في الفراش لغير عذر.',
      hanafi: 'إما أن تصبر بمعاشرة طيبة أو تطلب الطلاق للضرر.',
      maliki: 'الخيار لها بين الصبر بالمعروف أو طلب الفراق بالمعروف.',
      shafii: 'يثبت لها خيار الفسخ لتعذر النفقة ولا تجمع بين البقاء والنشوز.',
      hanbali: 'لها حق الفسخ لتعذر النفقة، والواجب عند البقاء في العصمة أداء الحقوق.',
      dalil: 'قوله تعالى: ﴿فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ﴾.',
    ),
    FiqhItem(
