      categoryId: 'marriage',
      question: 'كيفَ تحقق الزوجةُ طموحَها دونَ أن تهدم بيتها ؟',
      summary: 'بتحديد الأولويات، التنسيق والتفاهم المستمر مع الزوج، استثمار أوقات الفراغ، التنازل عن الكماليات، وجعل استقرار الأسرة وسعادة الأبناء الأساس الراسخ.',
