      shafii: 'التشاور والتراضي مفتاح النجاح الأسري والمهني.',
      hanbali: 'الموازنة بين الواجبات الزوجية وتحقيق الذات بالمعروف.',
      dalil: 'قوله تعالى: ﴿وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ﴾.',
    ),
    FiqhItem(
