      categoryId: 'marriage',
      question: 'أدبُ الدخولِ على العروس.. لمساتٌ نبويةٌ تزرعُ الطمأنينةَ',
      summary: 'ملاطفة العروس بهدية أو شراب، وضع اليد على ناصيتها والدعاء بالبركة، صلاة ركعتين خفيفتين جماعة، والتحدث بلطف وهدوء يزيل الخوف والوجل.',
      hanafi: 'يسن الدعاء بالمأثور وركعتا الاستفتاح.',
