      shafii: 'يسن صلاة ركعتين والدعاء بالبركة والمودة.',
      hanbali: 'الدعاء بالخير والملاطفة بالقول اللين تأسياً بالنبي ﷺ.',
      dalil: 'حديث عبد الله بن مسعود وأبي سعيد في سنن وآداب الدخول على الأهل.',
