    FiqhItem(
      id: 'marriage_72',
      categoryId: 'marriage',
      question: 'الممنوع والمسموح في الفراش: حقائق يجب معرفتها',
      summary: 'يباح للزوجين كل أنواع الاستمتاع والملاعبة، ويحرم أمران بالإجماع والتحريم القاطع: الجماع في الدبر (كبيرة ملعون فاعلها)، والجماع في الفرج أثناء الحيض والنفاس حتى تطهر وتغتسل.',
      hanafi: 'يحرم الإتيان في الدبر ووقت الحيض ويباح ما عدا ذلك.',
      maliki: 'الوطء في الدبر حرام وكبيرة مغلظة، والوطء في الحيض حرام بنص التنزيل.',
      shafii: 'يحرم الجماع في الدبر والحيض، ويباح الاستمتاع بسائر البدن.',
      hanbali: 'محرمان بالإجماع: الدبر والحيض، وسائر الاستمتاع مباح بالتراضي.',
      dalil: 'قوله تعالى: ﴿فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ﴾ وقوله ﷺ: «ملعون من أتى امرأته في دبرها».',
    ),
    FiqhItem(
      id: 'hajj_1',
      categoryId: 'hajj',
      question: 'ما صفة العمرة للمرأة ؟',
      summary: 'الإحرام من الميقات، الطواف بالبيت 7 أشواط مع الطهارة والستر، صلاة ركعتين خلف المقام، السعي بين الصفا والمروة 7 أشواط، والتقصير بقص أنملة (2 سم) من أطراف شعرها.',
      hanafi: 'الإحرام، الطواف، السعي، والتقصير.',
      maliki: 'أركانها: الإحرام والطواف والسعي، والواجب الحلق أو التقصير.',
      shafii: 'الأركان: الإحرام، الطواف، السعي، التقصير، والترتيب.',
      hanbali: 'الإحرام، الطواف، السعي، وقص قدر أنملة من كل ضفيرة وقرن.',
      dalil: 'قوله تعالى: ﴿وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ﴾ وصفة عمرة النبي ﷺ وأصحابه.',
    ),
    FiqhItem(
      id: 'hajj_2',
      categoryId: 'hajj',
      question: 'هل يمكن تكرار العمرة في سفر واحد؟',
      summary: 'جائز عند الجمهور بالخروج إلى التنعيم أو أدنى الحِل والإحرام، والأفضل والأكثر أجراً الإكثار من الطواف والصلاة في الحرم بدلاً من تكرار العمرة في السفر الواحد.',
      hanafi: 'يجوز تكرارها من أدنى الحِل كالتنعيم.',
      maliki: 'يكره تكرارها في السفر الواحد والأفضل الطواف.',
      shafii: 'جائز الخروج للتنعيم والإحرام بعمرة جديدة.',
      hanbali: 'جائز، ولكن هدي النبي ﷺ وأصحابه كان الاكتفاء بعمرة واحدة في السفر والإكثار من الطواف.',
      dalil: 'حديث إحرام عائشة رضي الله عنها من التنعيم بأمر النبي ﷺ لأخيها عبد الرحمن.',
    ),
    FiqhItem(
      id: 'hajj_3',
      categoryId: 'hajj',
      question: 'هل يصح بدء الطواف قبل الحجر الأسود ؟',
      summary: 'يجب بدء كل شوط من الحجر الأسود (أو محاذاته التامة بمحاذاة الخط والشاخص)، ولا يعتد بما يطاف قبله حتى يحاذي الحجر الأسود.',
