      maliki: 'شرط صحة الطواف ابتداؤه من الحجر الأسود.',
      shafii: 'ركن في الطواف أن يبدأ من الحجر الأسود بمحاذاة جميع بدنه.',
      hanbali: 'يبدأ من الحجر الأسود وينتهي إليه، وما طافه قبله لاغٍ.',
      dalil: 'فعل النبي ﷺ حين استلم الركن وابتدأ طوافه منه.',
