    ),
    FiqhItem(
      id: 'hajj_5',
      categoryId: 'hajj',
      question: 'خرج منها إفرازات أثناء العمرة ؟',
      summary: 'إن كانت إفرازات طهارة عادية وانتقض وضوؤها أثناء الطواف توضأت وأكملت طوافها عند الجمهور، وأما في السعي فلا تشترط الطهارة وسعيها صحيح.',
      hanafi: 'تتوضأ وتكمل طوافها وسعيها صحيح ولو بلا وضوء.',
