      shafii: 'تتوضأ وتبني على ما طافت وتستمر في سعيها.',
      hanbali: 'تتطهر للطواف، والسعي يصح من الحائض والنفساء ومحدثة الحدث الأصغر.',
      dalil: 'قول النبي ﷺ لعائشة: «افعلي ما يفعل الحاج غير ألا تطوفي بالبيت حتى تطهري».',
