  static List<FiqhItem> getByCategory(String categoryId) {
    return allItems.where((item) => item.categoryId == categoryId).toList();
  }

  static List<FiqhItem> search(String query) {
    if (query.trim().isEmpty) return allItems;
    final q = query.trim().toLowerCase();
    return allItems.where((item) {
      return item.question.toLowerCase().contains(q) ||
          item.summary.toLowerCase().contains(q) ||
          item.hanafi.toLowerCase().contains(q) ||
          item.maliki.toLowerCase().contains(q) ||
          item.shafii.toLowerCase().contains(q) ||
          item.hanbali.toLowerCase().contains(q);
    }).toList();
  }
}
